-- JEC-conNEcT: workspace activity feed and private user notifications.
-- All writes are generated by trusted database triggers; clients can only read their own notifications
-- and mark them as read. No message body, transcript or meeting content is copied into notifications.

create table if not exists public.jec_user_notifications (
  id uuid primary key default gen_random_uuid(),
  recipient_id uuid not null references auth.users(id) on delete cascade,
  actor_id uuid references auth.users(id) on delete set null,
  workspace_id uuid references public.jec_workspaces(id) on delete set null,
  event_type text not null check (char_length(event_type) between 2 and 80),
  entity_type text not null check (entity_type in ('task','meeting','message','task_comment')),
  entity_id uuid,
  title_fr text not null check (char_length(title_fr) between 1 and 180),
  title_en text not null check (char_length(title_en) between 1 and 180),
  body_fr text not null default '' check (char_length(body_fr) <= 500),
  body_en text not null default '' check (char_length(body_en) <= 500),
  target_path text not null default '/workspace' check (target_path ~ '^/[A-Za-z0-9/_?&=.-]*$'),
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists idx_jec_user_notifications_recipient_created on public.jec_user_notifications(recipient_id,created_at desc);
create index if not exists idx_jec_user_notifications_unread on public.jec_user_notifications(recipient_id,created_at desc) where read_at is null;
alter table public.jec_user_notifications enable row level security;
revoke all on public.jec_user_notifications from anon,authenticated;
grant select on public.jec_user_notifications to authenticated;
grant update (read_at) on public.jec_user_notifications to authenticated;
drop policy if exists "Users read their own JEC notifications" on public.jec_user_notifications;
create policy "Users read their own JEC notifications" on public.jec_user_notifications for select to authenticated using (recipient_id=(select auth.uid()));
drop policy if exists "Users mark their own JEC notifications as read" on public.jec_user_notifications;
create policy "Users mark their own JEC notifications as read" on public.jec_user_notifications for update to authenticated using (recipient_id=(select auth.uid())) with check (recipient_id=(select auth.uid()));

create table if not exists public.jec_activity_events (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.jec_workspaces(id) on delete cascade,
  project_id uuid references public.jec_projects(id) on delete set null,
  actor_id uuid references auth.users(id) on delete set null,
  entity_type text not null check (entity_type in ('project','task','milestone','meeting')),
  entity_id uuid not null,
  event_type text not null check (char_length(event_type) between 2 and 80),
  summary_fr text not null check (char_length(summary_fr) between 1 and 500),
  summary_en text not null check (char_length(summary_en) between 1 and 500),
  created_at timestamptz not null default now()
);
create index if not exists idx_jec_activity_project_created on public.jec_activity_events(project_id,created_at desc);
create index if not exists idx_jec_activity_workspace_created on public.jec_activity_events(workspace_id,created_at desc);
alter table public.jec_activity_events enable row level security;
revoke all on public.jec_activity_events from anon,authenticated;
grant select on public.jec_activity_events to authenticated;
drop policy if exists "Workspace members read their activity feed" on public.jec_activity_events;
create policy "Workspace members read their activity feed" on public.jec_activity_events for select to authenticated
using (private.is_jec_admin() or private.is_jec_workspace_member(workspace_id));

create or replace function private.jec_insert_notification(
  target_recipient_id uuid,target_actor_id uuid,target_workspace_id uuid,target_event_type text,target_entity_type text,target_entity_id uuid,
  target_title_fr text,target_title_en text,target_body_fr text,target_body_en text,target_path text
) returns void language plpgsql security definer set search_path='' as $$
begin
  if target_recipient_id is null or target_recipient_id=target_actor_id then return; end if;
  insert into public.jec_user_notifications(recipient_id,actor_id,workspace_id,event_type,entity_type,entity_id,title_fr,title_en,body_fr,body_en,target_path)
  values(target_recipient_id,target_actor_id,target_workspace_id,target_event_type,target_entity_type,target_entity_id,left(target_title_fr,180),left(target_title_en,180),
    left(coalesce(target_body_fr,''),500),left(coalesce(target_body_en,''),500),
    case when target_path ~ '^/[A-Za-z0-9/_?&=.-]*$' then target_path else '/workspace' end);
end;
$$;
revoke all on function private.jec_insert_notification(uuid,uuid,uuid,text,text,uuid,text,text,text,text,text) from public,anon,authenticated;

create or replace function private.jec_insert_activity_event(
  target_workspace_id uuid,target_project_id uuid,target_actor_id uuid,target_entity_type text,target_entity_id uuid,target_event_type text,target_summary_fr text,target_summary_en text
) returns void language plpgsql security definer set search_path='' as $$
begin
  if target_workspace_id is null or target_entity_id is null then return; end if;
  insert into public.jec_activity_events(workspace_id,project_id,actor_id,entity_type,entity_id,event_type,summary_fr,summary_en)
  values(target_workspace_id,target_project_id,target_actor_id,target_entity_type,target_entity_id,target_event_type,left(target_summary_fr,500),left(target_summary_en,500));
end;
$$;
revoke all on function private.jec_insert_activity_event(uuid,uuid,uuid,text,uuid,text,text,text) from public,anon,authenticated;

create or replace function private.jec_notify_task_assignment() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid := coalesce((select auth.uid()),new.created_by); target_path text := case when new.project_id is not null then '/projets/'||new.project_id::text else '/workspace' end;
begin
  if new.assigned_to is not null and (tg_op='INSERT' or old.assigned_to is distinct from new.assigned_to) then
    perform private.jec_insert_notification(new.assigned_to,actor,new.workspace_id,'task_assigned','task',new.id,'Nouvelle tâche attribuée','New task assigned',new.title,new.title,target_path);
  end if;
  return new;
end;
$$;
revoke all on function private.jec_notify_task_assignment() from public,anon,authenticated;
drop trigger if exists trg_jec_notify_task_assignment on public.jec_workspace_tasks;
create trigger trg_jec_notify_task_assignment after insert or update of assigned_to on public.jec_workspace_tasks for each row execute function private.jec_notify_task_assignment();

create or replace function private.jec_notify_meeting_invitation() returns trigger language plpgsql security definer set search_path='' as $$
declare mt record; actor uuid;
begin
  if new.attendance_status<>'invited' then return new; end if;
  select id,workspace_id,title,created_by into mt from public.jec_meetings where id=new.meeting_id;
  actor:=coalesce((select auth.uid()),mt.created_by);
  perform private.jec_insert_notification(new.user_id,actor,mt.workspace_id,'meeting_invitation','meeting',new.meeting_id,
    'Invitation à une réunion','Meeting invitation',mt.title,mt.title,'/reunions/'||new.meeting_id::text);
  return new;
end;
$$;
revoke all on function private.jec_notify_meeting_invitation() from public,anon,authenticated;
drop trigger if exists trg_jec_notify_meeting_invitation on public.jec_meeting_participants;
create trigger trg_jec_notify_meeting_invitation after insert on public.jec_meeting_participants for each row execute function private.jec_notify_meeting_invitation();

create or replace function private.jec_notify_new_message() returns trigger language plpgsql security definer set search_path='' as $$
declare recipient record;
begin
  for recipient in
    select cm.user_id,c.workspace_id from public.jec_conversation_members cm
    join public.jec_conversations c on c.id=cm.conversation_id
    where cm.conversation_id=new.conversation_id and cm.membership_status='active' and cm.user_id<>new.sender_id
  loop
    perform private.jec_insert_notification(recipient.user_id,new.sender_id,recipient.workspace_id,'new_message','message',new.id,
      'Nouveau message','New message','Une nouvelle activité t’attend dans une conversation.','There is new activity in one of your conversations.','/messagerie');
  end loop;
  return new;
end;
$$;
revoke all on function private.jec_notify_new_message() from public,anon,authenticated;
drop trigger if exists trg_jec_notify_new_message on public.jec_messages;
create trigger trg_jec_notify_new_message after insert on public.jec_messages for each row execute function private.jec_notify_new_message();

create or replace function private.jec_notify_task_comment() returns trigger language plpgsql security definer set search_path='' as $$
declare task_row record; target_path text;
begin
  select id,workspace_id,project_id,title,created_by,assigned_to into task_row from public.jec_workspace_tasks where id=new.task_id;
  target_path:=case when task_row.project_id is not null then '/projets/'||task_row.project_id::text else '/workspace' end;
  if task_row.created_by is not null and task_row.created_by<>new.author_id then
    perform private.jec_insert_notification(task_row.created_by,new.author_id,task_row.workspace_id,'task_comment','task_comment',new.id,
      'Nouveau commentaire sur une tâche','New task comment',task_row.title,task_row.title,target_path);
  end if;
  if task_row.assigned_to is not null and task_row.assigned_to<>new.author_id and task_row.assigned_to is distinct from task_row.created_by then
    perform private.jec_insert_notification(task_row.assigned_to,new.author_id,task_row.workspace_id,'task_comment','task_comment',new.id,
      'Nouveau commentaire sur ta tâche','New comment on your task',task_row.title,task_row.title,target_path);
  end if;
  return new;
end;
$$;
revoke all on function private.jec_notify_task_comment() from public,anon,authenticated;
drop trigger if exists trg_jec_notify_task_comment on public.jec_task_comments;
create trigger trg_jec_notify_task_comment after insert on public.jec_task_comments for each row execute function private.jec_notify_task_comment();

create or replace function private.jec_track_project_activity() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid := coalesce((select auth.uid()),new.created_by);
begin
  if tg_op='INSERT' then
    perform private.jec_insert_activity_event(new.workspace_id,new.id,actor,'project',new.id,'project_created','Projet créé : '||new.title,'Project created: '||new.title);
  elsif old.project_status is distinct from new.project_status or old.priority is distinct from new.priority or old.owner_id is distinct from new.owner_id or old.due_date is distinct from new.due_date then
    perform private.jec_insert_activity_event(new.workspace_id,new.id,actor,'project',new.id,'project_updated','Paramètres du projet modifiés : '||new.title,'Project settings updated: '||new.title);
  end if;
  return new;
end;
$$;
revoke all on function private.jec_track_project_activity() from public,anon,authenticated;
drop trigger if exists trg_jec_track_project_activity on public.jec_projects;
create trigger trg_jec_track_project_activity after insert or update on public.jec_projects for each row execute function private.jec_track_project_activity();

create or replace function private.jec_track_task_activity() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid := coalesce((select auth.uid()),new.created_by);
begin
  if tg_op='INSERT' then
    perform private.jec_insert_activity_event(new.workspace_id,new.project_id,actor,'task',new.id,'task_created','Tâche créée : '||new.title,'Task created: '||new.title);
  elsif old.task_status is distinct from new.task_status or old.priority is distinct from new.priority or old.assigned_to is distinct from new.assigned_to or old.due_at is distinct from new.due_at then
    perform private.jec_insert_activity_event(new.workspace_id,new.project_id,actor,'task',new.id,'task_updated','Tâche mise à jour : '||new.title,'Task updated: '||new.title);
  end if;
  return new;
end;
$$;
revoke all on function private.jec_track_task_activity() from public,anon,authenticated;
drop trigger if exists trg_jec_track_task_activity on public.jec_workspace_tasks;
create trigger trg_jec_track_task_activity after insert or update on public.jec_workspace_tasks for each row execute function private.jec_track_task_activity();

create or replace function private.jec_track_milestone_activity() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid := coalesce((select auth.uid()),new.created_by);
begin
  if tg_op='INSERT' then
    perform private.jec_insert_activity_event(new.workspace_id,new.project_id,actor,'milestone',new.id,'milestone_created','Jalon ajouté : '||new.title,'Milestone added: '||new.title);
  elsif old.milestone_status is distinct from new.milestone_status or old.due_date is distinct from new.due_date or old.owner_id is distinct from new.owner_id then
    perform private.jec_insert_activity_event(new.workspace_id,new.project_id,actor,'milestone',new.id,'milestone_updated','Jalon mis à jour : '||new.title,'Milestone updated: '||new.title);
  end if;
  return new;
end;
$$;
revoke all on function private.jec_track_milestone_activity() from public,anon,authenticated;
drop trigger if exists trg_jec_track_milestone_activity on public.jec_project_milestones;
create trigger trg_jec_track_milestone_activity after insert or update on public.jec_project_milestones for each row execute function private.jec_track_milestone_activity();

create or replace function private.jec_track_meeting_activity() returns trigger language plpgsql security definer set search_path='' as $$
declare actor uuid := coalesce((select auth.uid()),new.created_by);
begin
  if tg_op='INSERT' then
    perform private.jec_insert_activity_event(new.workspace_id,new.project_id,actor,'meeting',new.id,'meeting_scheduled','Réunion programmée : '||new.title,'Meeting scheduled: '||new.title);
  elsif old.meeting_status is distinct from new.meeting_status or old.starts_at is distinct from new.starts_at then
    perform private.jec_insert_activity_event(new.workspace_id,new.project_id,actor,'meeting',new.id,'meeting_updated','Réunion mise à jour : '||new.title,'Meeting updated: '||new.title);
  end if;
  return new;
end;
$$;
revoke all on function private.jec_track_meeting_activity() from public,anon,authenticated;
drop trigger if exists trg_jec_track_meeting_activity on public.jec_meetings;
create trigger trg_jec_track_meeting_activity after insert or update on public.jec_meetings for each row execute function private.jec_track_meeting_activity();

do $$
begin
  if exists (select 1 from pg_publication where pubname='supabase_realtime') then
    if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='jec_user_notifications') then
      execute 'alter publication supabase_realtime add table public.jec_user_notifications';
    end if;
    if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='jec_activity_events') then
      execute 'alter publication supabase_realtime add table public.jec_activity_events';
    end if;
  end if;
end;
$$;
comment on table public.jec_user_notifications is 'Private per-user notifications. Clients can only read their own rows and update read_at.';
comment on table public.jec_activity_events is 'Private, read-only timeline of workspace project, task, milestone and meeting activity.';
